package com.luckyalanzhou.barcodegenerator.data.network.web

/** 浏览器传输页的 CSS 模板。 */
internal object LanShareWebStyles {
    fun render() = """<style>
:root{color-scheme:light dark;--bg:#f4f6fb;--panel:#fff;--text:#172033;--line:#d9e0ea;--sub:#667085;--bubble-peer:rgba(255,255,255,.72);--bubble-mine:rgba(10,132,255,.88);--bubble-border:rgba(71,91,122,.18);--bubble-mine-border:rgba(147,197,253,.78);--bubble-shadow:rgba(31,41,55,.1);--preview-bg:rgba(15,23,42,.08);--link:#075fbe;--accent:#0a84ff}@media(prefers-color-scheme:dark){:root{--bg:#000;--panel:#1d1d1f;--text:#f5f5f7;--line:#3a3a3c;--sub:#a1a1a6;--bubble-peer:rgba(44,44,46,.94);--bubble-mine:rgba(10,132,255,.92);--bubble-border:rgba(255,255,255,.14);--bubble-mine-border:rgba(120,190,255,.72);--bubble-shadow:rgba(0,0,0,.38);--preview-bg:rgba(255,255,255,.08);--link:#72b7ff;--accent:#0a84ff}}*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,sans-serif;margin:0;color:var(--text);background:var(--bg)}main{max-width:560px;margin:auto;min-height:100vh;padding-bottom:86px}.bar{display:flex;align-items:center;justify-content:space-between;padding:18px 20px 12px;font-size:20px;font-weight:700}.connection-status{font-size:13px;font-weight:500;color:var(--sub);white-space:nowrap}.connection-status.connected{color:#22c55e}ul{display:flex;flex-direction:column;align-items:flex-start;gap:10px;padding:0 14px;margin:0}li{display:flex;align-items:center;gap:12px;width:fit-content;max-width:78%;padding:10px 14px;border:1px solid var(--bubble-border);border-radius:18px;list-style:none;background:var(--bubble-peer);box-shadow:0 10px 28px var(--bubble-shadow),inset 0 1px rgba(255,255,255,.32);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}li.mine{align-self:flex-end;background:var(--bubble-mine);border-color:var(--bubble-mine-border);color:#fff}li.peer{align-self:flex-start}li.mine a:first-of-type,li.mine small{color:#fff}.image-item{flex-direction:column;align-items:flex-start;padding:6px;gap:8px}.media-preview{width:auto;max-width:100%;height:auto;max-height:260px;object-fit:contain;align-self:center;border-radius:12px;background:var(--preview-bg)}li:not(.image-item)::before{content:'📎';font-size:22px}li a:first-of-type{min-width:0;flex:1;overflow-wrap:anywhere;color:var(--link)}small{display:block;color:var(--sub);margin-top:4px}.download{padding:8px 13px;border:1px solid var(--line);border-radius:999px;color:var(--accent);text-decoration:none;background:rgba(255,255,255,.18)}.mine .download{color:#fff;border-color:rgba(255,255,255,.5);background:rgba(0,0,0,.12)}.bottom{position:fixed;bottom:0;left:0;right:0;background:var(--panel);padding:14px}.bottom form{display:flex;align-items:center;gap:8px;max-width:560px;margin:auto}.file-picker,.send-button{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid var(--line);border-radius:22px;cursor:pointer;flex:0 0 44px}.message-input{min-width:0;flex:1;height:44px;padding:0 14px;border:1px solid var(--line);border-radius:22px;background:transparent;color:var(--text);font:inherit}.send-button{background:var(--accent);color:white}.attachment-sheet{display:none;position:fixed;width:154px;padding:6px;border:1px solid var(--line);border-radius:20px;background:var(--panel);box-shadow:0 16px 40px var(--bubble-shadow);z-index:10}.attachment-sheet.open{display:flex;flex-direction:column}.attachment-sheet button{width:100%;min-height:38px;border:0;border-top:1px solid rgba(71,91,122,.2);background:transparent;color:var(--text);font:inherit}.attachment-sheet button:first-child{border-top:0}
</style></head>"""
}
